from collections import OrderedDict
from typing import List, Tuple, Dict, Generator, Union
from uuid import uuid4

class Message:
    def __init__(self, text: str, locations: List[Tuple[str, int]], uuids: List[str]):
        self.text = text
        self.locations = locations
        self.uuids = uuids

class Catalog:
    def __init__(self) -> None:
        self.messages: List[str] = []
        self.metadata: Dict[str, List[Tuple[str, int, str]]] = OrderedDict()

    def add(self, msg: str, source: str, line: int, uid: str) -> None:
        if msg not in self.metadata:
            self.messages.append(msg)
            self.metadata[msg] = []
        self.metadata[msg].append((source, line, uid))

    def __iter__(self) -> Generator[Message, None, None]:
        for message in self.messages:
            seen_positions = set()
            positions = []
            uuids = []
            for source, line, uuid in self.metadata[message]:
                if (source, line) not in seen_positions:
                    positions.append((source, line))
                    uuids.append(uuid)
                    seen_positions.add((source, line))
            yield Message(message, positions, uuids)

if __name__ == "__main__":
    catalog = Catalog()
    msg_id = "Type"
    catalog.add(msg_id, "file.rst", 10, "uuid1")
    catalog.add(msg_id, "file.rst", 10, "uuid2")

    for msg in catalog:
        print(f"Locations: {msg.locations}")
        print(f"UUIDs: {msg.uuids}")
        assert len(msg.locations) == len(msg.uuids)
        assert len(msg.locations) == 1

